--- a/lib/editor/sheet.dart
+++ b/lib/editor/sheet.dart
@@ -20,6 +20,11 @@
     super.initState();
     WidgetsBinding.instance.addPostFrameCallback((_) {
+      final draft = ref.read(draftProvider);
+      final route = ref.read(routeProvider);
+      if (draft == null || route == null) return;
+      ref.read(draftProvider.notifier).state = null;
+      _open(draft.id, route);
       _restore();
     });
